window.STORY_CHAPTERS["c977b4daf4b161b4e"]={"id":"c977b4daf4b161b4e","lines":[{"uid":"talk.vc.home_etc_sortiliena_child_1#originalText","id":"talk.vc.home_etc_sortiliena_child_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你达成任务了吗？恭喜你。","en":"Did a new mission arrive? Congratulations.","ja":"任務を達成したのか? おめでとう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sortiliena_child_2#originalText","id":"talk.vc.home_etc_sortiliena_child_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"这好像是礼物。里面装的说不定是武器喔。","en":"Looks like a gift. There might be a weapon inside...","ja":"贈り物みたいだな中は武器かもしれないぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_sortiliena_child_3#originalText","id":"talk.vc.home_etc_sortiliena_child_3","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"有下一件任务。来，我们去看看吧。","en":"The next mission is in. Let's go see what it is!","ja":"次の任務ださあ、見に行こう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_strea_1#originalText","id":"talk.vc.home_etc_strea_1","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"恭喜你达成使命！来来来，报酬已经送到啰！","en":"Congrats on clearing that Mission! The reward is all yours!","ja":"ミッション達成おめでとう!ほらほら、報酬が届いてるよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_strea_2#originalText","id":"talk.vc.home_etc_strea_2","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"听说有礼物－－！是什么啊？快打开给我看看！","en":"You got a present. Hurry up and open it!","ja":"プレゼントだってー!なになに、開けて見せてよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_strea_3#originalText","id":"talk.vc.home_etc_strea_3","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"新的任务来啰！你愿意的话要不要一起解呢？","en":"I new quest just came in! Would you mind if we both went and checked it out?","ja":"新しいクエストが入ってるんだって!よかったら、一緒に見に行かない?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_subtilizer_1#originalText","id":"talk.vc.home_etc_subtilizer_1","speaker":{"ja":"サトライザー"},"text":{"ja":"仕事が終わったら速やかに報告せよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_subtilizer_2#originalText","id":"talk.vc.home_etc_subtilizer_2","speaker":{"ja":"サトライザー"},"text":{"ja":"自分に贈られた物くらい自分で管理できぬのか"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_subtilizer_3#originalText","id":"talk.vc.home_etc_subtilizer_3","speaker":{"ja":"サトライザー"},"text":{"ja":"お前には次の仕事があるのではないか?何を呆けている?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_suguha_1#originalText","id":"talk.vc.home_etc_suguha_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"恭喜你达成使命！要持续向前进喔！","en":"Congrats on clearing that Mission. Let's keep pushing through!","ja":"ミッション達成、おめでとう! どんどん進んでいっちゃうね! "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_suguha_2#originalText","id":"talk.vc.home_etc_suguha_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"收到礼物啰，打开看看吧？","en":"You've got a present. Wanna open it?","ja":"プレゼントが届いてるよ開けてみたら? "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_suguha_3#originalText","id":"talk.vc.home_etc_suguha_3","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"出现新任务了！会是什么内容呢……","en":"A new Quest came out! I wonder what's in it.","ja":"新しいクエストが出現したよ! どんな内容だろう……"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_tiese_1#originalText","id":"talk.vc.home_etc_tiese_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"达成使命了呢。您平安无事真是太好了。","en":"You accomplished a mission, I see! I am so glad you're home safe.","ja":"使命、達成されたのですね本当にご無事でよかったです"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_tiese_2#originalText","id":"talk.vc.home_etc_tiese_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长，好像有礼物。赶紧打开来看看吧。","en":"Sir, a gift has arrived for you. Let's open it!","ja":"先輩、贈り物があるみたいです早く開けてみましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_tiese_3#originalText","id":"talk.vc.home_etc_tiese_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"新的使命送来了。有很多人仰赖学长的力量呢。","en":"A new mission has arrived for you. I can tell many people depend on you.","ja":"新しい使命が届いています先輩の力を必要としている方がたくさんいるんですね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_tiese_child_1#originalText","id":"talk.vc.home_etc_tiese_child_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"达成使命了。下次请让我帮忙吧！","en":"Looks like you've completed the mission. Please let me assist you next time!","ja":"使命達成したんですね次はあたしもお手伝いさせてください!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_tiese_child_2#originalText","id":"talk.vc.home_etc_tiese_child_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"是寄给你的礼物。那个……要不要快点打开来看看呢？","en":"It's a present addressed to you. Um...should we hurry up and check what's inside?","ja":"あなた宛の贈り物ですあの……早く中身を見てみませんか?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_tiese_child_3#originalText","id":"talk.vc.home_etc_tiese_child_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"是新的使命呢。加油！记得不要太勉强自己！","en":"A new mission! Please do your best and don't over do it!","ja":"新たな使命ですね無理しないで頑張ってください!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_vassago_1#originalText","id":"talk.vc.home_etc_vassago_1","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"啧，成功完成使命了吗。一点都不有趣。","en":"Tch. Mission accomplished, eh? How dull.","ja":"ち、ミッション成功か面白くねぇ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_vassago_2#originalText","id":"talk.vc.home_etc_vassago_2","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"打开礼物时记得小心点。说不定会发出Bomb!的声音。","en":"You better be careful opening up presents. Who knows, it might be a Bomb!","ja":"プレゼントを開けるときには注意しなBomb!といくかもしれねえぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_vassago_3#originalText","id":"talk.vc.home_etc_vassago_3","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"快点出发去下一个地点吧。我会在那里杀了你。","en":"Hurry up and get to the next mission! That's where I'll kill you!","ja":"とっとと次へ行きなそこで殺してやるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_vector_1#originalText","id":"talk.vc.home_etc_vector_1","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"完成工作后就迅速报告吧。","en":"Report to me immediately once the job is finished."},"kind":"dialogue"},{"uid":"talk.vc.home_etc_vector_2#originalText","id":"talk.vc.home_etc_vector_2","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"难道你连送给自己的东西也不能好好管理吗。","en":"You can't even take care of your own presents?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_vector_3#originalText","id":"talk.vc.home_etc_vector_3","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"你不是还有工作吗？发什么呆？","en":"Don't you have another job? What are you dazing off about?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_volo_1#originalText","id":"talk.vc.home_etc_volo_1","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"你达成使命啦。这种程度不费你吹灰之力，是这样没错吧。","en":"You accomplished a mission, eh? Then I suppose it wasn't a difficult task.","ja":"使命を達成したかこの程度は造作もないということだな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_volo_2#originalText","id":"talk.vc.home_etc_volo_2","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"这个礼物好像是给你的。","en":"This gift is addressed to you, apparently.","ja":"この贈り物はお前宛のようだ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_volo_3#originalText","id":"talk.vc.home_etc_volo_3","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"下一个使命啊？不知道我跟你，谁能较快达成呢？","en":"The next mission is in? Let's compete to see which of us finishes first.","ja":"次の使命か私とお前、どちらが早く達成できるかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_yui_1#originalText","id":"talk.vc.home_etc_yui_1","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"完成使命！爸爸果然厉害！","en":"You cleared the Mission! I knew you could do it.","ja":"ミッションクリアです!さすがですね!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_yui_2#originalText","id":"talk.vc.home_etc_yui_2","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"收到礼物啰。会是谁送来的呢？","en":"You've got a present. Who could it be from?","ja":"プレゼントが届いていますよどなたからでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_yui_3#originalText","id":"talk.vc.home_etc_yui_3","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"开放新任务啰！是什么样的任务呢？","en":"A new Quest came out! I wonder what's in it.","ja":"新しいクエストが開放されましたね!どんな内容ですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_yuna_1#originalText","id":"talk.vc.home_etc_yuna_1","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"恭喜你达成使命！对你而言，不管是什么使命都不成威胁呢！","en":"Congrats on clearing that Mission! Any mission thrown your way is no biggie for you!","ja":"ミッション達成、おめでとう!あなたにかかれば、どんなミッションも敵じゃないわね!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_yuna_2#originalText","id":"talk.vc.home_etc_yuna_2","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"好像有署名给你的礼物喔。里面装了什么呢？","en":"Looks like a present addressed to you arrived. What could be inside?","ja":"あなた宛のプレゼントがあるみたいね中身はなあに?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_yuna_3#originalText","id":"talk.vc.home_etc_yuna_3","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"听说有新任务耶！欸，我们一起去看嘛。","en":"I heard a new quest just came in! How about we go see together?","ja":"新しいクエストがあるんだって!ねえ、一緒に行こうよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_yuuki_1#originalText","id":"talk.vc.home_etc_yuuki_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"完成使命～！你真厉害！","en":"You cleared the Mission! I knew you could do it.","ja":"ミッションクリアー! さすがだね! "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_yuuki_2#originalText","id":"talk.vc.home_etc_yuuki_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"你看你看，是礼物！里面一定装着很棒的东西啦！","en":"Come on, look, you got a present! I'm sure there's something awesome inside.","ja":"ほらほら、プレゼント! きっとステキなものが入ってるよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_yuuki_3#originalText","id":"talk.vc.home_etc_yuuki_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"听说实装新任务了，你会去看吧？","en":"I hear a new Quest is out. You're gonna go check it out, right?","ja":"新しいクエストが実装されたってもちろん見に行くよね? "},"kind":"dialogue"},{"uid":"talk.vc.home_etc_zink_1#originalText","id":"talk.vc.home_etc_zink_1","speaker":{"cn":"吉克","en":"Zink","ja":"ジンク"},"text":{"cn":"达成使命啦？你挺厉害的嘛。","en":"You accomplished a mission? Good job, I guess.","ja":"使命の達成か?なかなかやるな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_zink_2#originalText","id":"talk.vc.home_etc_zink_2","speaker":{"cn":"吉克","en":"Zink","ja":"ジンク"},"text":{"cn":"说是给你的礼物啦。","en":"Hey, you got a gift.","ja":"お前に贈り物だってよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_zink_3#originalText","id":"talk.vc.home_etc_zink_3","speaker":{"cn":"吉克","en":"Zink","ja":"ジンク"},"text":{"cn":"下一份工作是什么？快点告诉我啦！","en":"What's the next assignment? Hurry up and tell me!","ja":"次の仕事は何だ?早く教えろよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_1#originalText","id":"talk.vc.home_event_alice_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这个既柔软又具延展性的东西……还挺好吃的。","en":"This soft, stretchy food... It's rather delicious. It’s called mochi?","ja":"この、柔らかくて伸びるものは……なかなかおいしいですね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_2#originalText","id":"talk.vc.home_event_alice_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"原来是驱除恶鬼的仪式啊。所以，才会用到这副面具吗？","en":"Ah, so it is a ceremony to ward off evil. Is that why you are wearing that mask?","ja":"悪鬼を払う儀式なのですねそれで、この仮面なのですか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_3#originalText","id":"talk.vc.home_event_alice_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"把点心，送给心仪的对象……我、我没有要给你！不过，如果你真的坚持……","en":"I'm supposed to give chocolate...to my beloved... D-don't get cocky! It isn't you! However, if you insist...","ja":"好きな相手へ、お菓子を……お、お前にではありません! ですが、どうしてもと言うなら……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_4#originalText","id":"talk.vc.home_event_alice_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"甜酒，是吗……非常好喝呢。我可以再喝一杯吗？","en":"Amazake...you say? It's rather tasty. May I have another cup?","ja":"甘酒、ですか……なかなか美味ですねもう一杯いただけますか? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_5#originalText","id":"talk.vc.home_event_alice_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"如果这代表你的心意，我也不忍心弃若敝屣。……谢谢你。","en":"If this is a token of your feelings, then it would be rude to refuse it. Thank you...","ja":"これがお前の気持ちであるなら無下にするのも気が引けます……ありがとう"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_6#originalText","id":"talk.vc.home_event_alice_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你又说谎了对吧？很好，我今天不会再听你说话了！","en":"You lied again. I will not listen to another word you have to say today!","ja":"お前はまた嘘をつきましたねもう、今日はお前の言うことは聞きません! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_7#originalText","id":"talk.vc.home_event_alice_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我要利用这次休假，勤加修练好能超越你。你呢？有什么安排？","en":"I am spending my vacation training to surpass your level. How do you plan on spending it?","ja":"この休暇の間、私はお前を超えるために修練を積みますお前はどうするのですか? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_8#originalText","id":"talk.vc.home_event_alice_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"多亏有雨，树木跟繁花都生气蓬勃呢。","en":"Thanks to the rain, the trees and flowers are full of life.","ja":"雨のおかげで、木々や花が生き生きしていますね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_9#originalText","id":"talk.vc.home_event_alice_9","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"银河……是吗？那是条连飞龙都无法飞越的河吗？","en":"The milky way, you say? Is it a \"way\" that cannot be crossed, even by flying dragon?","ja":"天の川……ですかそれは飛竜でも越えられない川なのですか? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_10#originalText","id":"talk.vc.home_event_alice_10","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"鉴于你如此坚持，我就跟你一起去夏至祭典吧。既然决定了，就赶紧出发吧！","en":"If you insist, I will attend the Summer Festival with you. Now that’s settled...we must make haste!","ja":"お前がどうしても、というなら夏至祭、ともに行きましょうそうと決まれば、急ぎますよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_11#originalText","id":"talk.vc.home_event_alice_11","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"因假期将届，而焦躁……还真有你的风格呢，说真的。","en":"You're stressed over your impending deadlines... Actually, this behavior is very like you.","ja":"期限が迫って、焦る……お前らしいですね、実に"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_12#originalText","id":"talk.vc.home_event_alice_12","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"月色看起来真美。既大、又明亮……这还是我第一次看到这种月亮。","en":"The moon is so bright tonight. I've never seen a moon so big...so divine.","ja":"月が綺麗に見えます明るく、大きく……このような月は、初めてみました"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_13#originalText","id":"talk.vc.home_event_alice_13","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"Trick or Treat。赌上糖果的比试……我这样理解对吗？","en":"Trick or treat... A competition for candy, perhaps?","ja":"トリック・オア・トリート菓子を賭けて勝負……という意味でしょうか? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_15#originalText","id":"talk.vc.home_event_alice_15","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这个叫蛋糕的东西还真好吃呢，我觉得不论份量多少都吃得下。","en":"This thing you call \"cake\" is delicious. I could eat it all day.","ja":"この、ケーキというのはおいしいですねいくらでも食べられそうです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_1#originalText","id":"talk.vc.home_event_asuna_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"新年快乐！今年一整年也多多指教喔。","en":"Happy New Year! Let's make it a good one.","ja":"あけましておめでとうございます今年も一年、よろしくね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_2#originalText","id":"talk.vc.home_event_asuna_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"虽然打扫很辛苦，但还是想会撒豆子呢。","en":"Even though clean-up can be really annoying, I still want to throw beans for Setsubun.","ja":"片付けは大変だけどやっぱりちゃんと豆まきしたいよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_3#originalText","id":"talk.vc.home_event_asuna_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今年的巧克力也是我亲手做的喔。充满着我满满的爱喔。","en":"I made this year's chocolates myself, just like last time. I put in my secret ingredient... Love!","ja":"今年のチョコレートもちゃんと手作りだよ愛情もこもってるから、ね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_4#originalText","id":"talk.vc.home_event_asuna_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我小时候，常常会拿女儿节娃娃的道具玩扮家家酒呢。","en":"I remember I used to play with Hinamatsuri dolls a lot when I was little.","ja":"雛人形の道具を使って小さい頃はよくおままごとをしてたなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_5#originalText","id":"talk.vc.home_event_asuna_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"只要是你送我的，不论是什么我都很开心。","en":"I'm happy with any gift, as long as it's from you.","ja":"君からもらえるならなんだってうれしいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_6#originalText","id":"talk.vc.home_event_asuna_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"嗯……我想不太出有趣的谎话呢。","en":"Hmmm...I can't think of a fun April Fool's prank to pull.","ja":"うーん……面白い嘘って、なかなか思いつかないね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_7#originalText","id":"talk.vc.home_event_asuna_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今年的连假我们去哪里走走吧？人潮不多的地方比较好呢。","en":"Where should we go for our week off this year? I vote for a place away from all the crowds.","ja":"今年の連休はどこへ行こっか人の少ない所がいいね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_8#originalText","id":"talk.vc.home_event_asuna_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"在房间里听雨声，也是别有一番风味呢。","en":"The rain is like soothing music when you're inside.","ja":"部屋の中なら、雨の音もちょっと風情があるね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_9#originalText","id":"talk.vc.home_event_asuna_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"如果一年只能见上一面……一定会非常寂寞吧。","en":"If we only got to see each other once a year, I’d miss you so bad.","ja":"年に1回しか会えなかったら……きっと、すごく寂しいだろうな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_10#originalText","id":"talk.vc.home_event_asuna_10","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"要不要趁着夏天，大家一起去海水浴场玩？我觉得一定会很开心的。","en":"Want to go to the beach with the gang this summer? I think we'd have a lot of fun!","ja":"夏の間に、みんなで海水浴に行かない? きっと楽しいと思うんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_11#originalText","id":"talk.vc.home_event_asuna_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天就是暑假的最后一天啦～我们一起度过了好多时光，真开心呢！","en":"Today's the last day of summer vacation... I had a lot of fun spending so much time with you.","ja":"夏休みも今日で最後かあたくさん一緒にいられて楽しかったね! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_12#originalText","id":"talk.vc.home_event_asuna_12","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"还好今天放晴。你看，月亮看得很清楚呢。","en":"Good thing it's a clear night. Look how clearly you can see the moon!","ja":"今日は晴れてよかったねほら、あんなに月がきれいに見えるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_13#originalText","id":"talk.vc.home_event_asuna_13","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我想大家一定都会来，先把糖果准备好吧。","en":"I'm sure everyone will show up, so I'll get some candy.","ja":"きっとみんな来ると思うからお菓子を準備しておきましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_14#originalText","id":"talk.vc.home_event_asuna_14","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"……虽然并非全部都是好事，但对我而言，今天还是值得纪念的日子吧。","en":"Even though the experience wasn't 100% good... today still marks a special anniversary for me.","ja":"……いいことばかりじゃなかったけどそれでもわたしにとっては今日は記念日かな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_15#originalText","id":"talk.vc.home_event_asuna_15","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"对我来说，你就是圣诞老人喔。","en":"You're my Santa.","ja":"わたしにとっては君がサンタさんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_1#originalText","id":"talk.vc.home_event_edith_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"新的一年到了呢。不论迎接多少次，心境都会在这一天更新耶。","en":"A new year is upon us. This day always feels poignant to me, no matter how many years pass.","ja":"新しい年になったね何回迎えても、この日は気持ちが改まるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_2#originalText","id":"talk.vc.home_event_edith_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"要是撒个豆子就能把恶鬼全部赶走，那就天下太平啦。","en":"If throwing beans really did make all evil in this world be gone, I can't imagine anything finer.","ja":"豆をまいて悪鬼が全部出て行ってくれるなら、こんなにいいことはないね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_3#originalText","id":"talk.vc.home_event_edith_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你这是要给我的？其实啊，我也有所准备喔。","en":"Oh, is this for me? Actually, I got some for you, too.","ja":"これ、あたしにくれるの? あたしも、実は用意していたんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_4#originalText","id":"talk.vc.home_event_edith_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"集成骑士里也有很多女性，所以或许能接受这个祭典呢。","en":"Many of the Integrity Knights are female, so I think this custom might catch on.","ja":"整合騎士にも女性が多いからこのお祭りは受け入れられるかもしれないね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_5#originalText","id":"talk.vc.home_event_edith_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"回礼也来互相交换吧。呵呵，这真是好习俗，干脆每个月都来一次吧。","en":"A gift for the gift-giver? Hehe, I like this custom, too. I wish it happened every month.","ja":"お返しの方も交換だねふふ、これはいい習慣だわ毎月あってもいいくらい"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_6#originalText","id":"talk.vc.home_event_edith_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"要骗人还是会心痛，所以我就不玩了。","en":"Telling lies really does pain my heart, so I don't think I'll do it.","ja":"嘘をつくと、やっぱり心が痛いじゃない。だからやめておくわ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_7#originalText","id":"talk.vc.home_event_edith_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好久没放长假了，好想在圣堂里养生喔。","en":"I haven't had a long vacation in a while. So, I'd like to relax in the Cathedral.","ja":"久しぶりに長い休暇だからカセドラルでゆっくりしたいのよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_8#originalText","id":"talk.vc.home_event_edith_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"下雨会盖掉脚步声，最适合趁机去侦查了。","en":"Since the rain erases my footprints, it's ideal weather for spying.","ja":"雨は足音を消してくれるから偵察に行くにはもってこいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_9#originalText","id":"talk.vc.home_event_edith_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"如果一年只能见一次面，我还是会很寂寞耶。","en":"The lovers only get to meet once a year? I would die with loneliness.","ja":"年に1回逢うだけじゃやっぱりあたしは寂しいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_10#originalText","id":"talk.vc.home_event_edith_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"夏至祭典的音乐连这里都听得见呢。我们还是去蹓跶蹓跶吧？","en":"I can hear the Summer Festival all the way from here. Shall we slip out and take a look?","ja":"夏至祭の音がここまで聞こえるねやっぱり、ちょっと見に行かない?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_11#originalText","id":"talk.vc.home_event_edith_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"假期要结束了啊。没办法，继续工作吧。","en":"The break is over, is it? Oh well. Back to work.","ja":"お休み終わりか仕方ない、また働くか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_12#originalText","id":"talk.vc.home_event_edith_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我以前几乎没有悠闲地赏月过……这样其实也不错呢。","en":"I've never stared at the moon at length before. I like it, I could get used to this.","ja":"ゆっくり月を眺めるってあんまりしたことないから……いいね、こういうのも"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_13#originalText","id":"talk.vc.home_event_edith_13","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你怪异的装扮吓到我了。不过仔细一看，有点可爱呢。","en":"The strange costumes are a bit shocking. But upon closer examination, they're also rather adorable.","ja":"おかしな格好はびっくりするよでも、よく見るとちょっとかわいいかも"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_15#originalText","id":"talk.vc.home_event_edith_15","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"在空中飞的马配上发送礼物的老人……他该不会是集成骑士吧？","en":"So, he's a gentleman in red who flies on horses, to give gifts to children... Are you sure he isn't an Integrity Knight?","ja":"空飛ぶ馬に、贈り物を配るおじさんか……それってもしかしたら整合騎士じゃないの?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_1#originalText","id":"talk.vc.home_event_eugeo_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"已经是新的一年了呢。只觉得自己才刚离开卢利特，没想到时间过得这么快。","en":"A new year is already here. It seems like only yesterday that we left Rulid.","ja":"もう新しい年なんだねこの間ルーリッドを出た気がしたけど、あっという間だったね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_2#originalText","id":"talk.vc.home_event_eugeo_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"如果用神圣术把这颗豆子弹出去，效果大概会更好吧？","en":"Wouldn't the effects of these beans be more powerful if we threw them using Sacred Arts?","ja":"この豆、神聖術で飛ばせばもっと効果があるんじゃないかな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_3#originalText","id":"talk.vc.home_event_eugeo_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"这个，是缇洁给我的……我该怎么做才好！？","en":"Look at what Tiese gave me. I don't know what to do about this!","ja":"これ、ティーゼからもらったんだけど……どうしよう!?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_4#originalText","id":"talk.vc.home_event_eugeo_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"既然是在祝福女孩子，那是不是也该叫上缇洁跟罗妮耶呢？","en":"If this is a festival for girls, shouldn't we invite Tiese and Ronie?","ja":"女の子のお祝いならティーゼとロニエも呼んだらどうかな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_5#originalText","id":"talk.vc.home_event_eugeo_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"收下了就该回礼对吧。果然还是送点心比较恰当吗？","en":"Oh, so you give gifts back to the girls who gave you gifts? Candy would be the best gift, right?","ja":"もらったらお返しするんだねやっぱりお菓子がいいのかな? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_6#originalText","id":"talk.vc.home_event_eugeo_6","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天是可以说谎的日子啊……为什么会出现这种节日呢？","en":"It's a day where lying is okay? I wonder how that holiday came into being?","ja":"嘘を付いてもいい日か……どうしてそんな日ができたんだろう"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_7#originalText","id":"talk.vc.home_event_eugeo_7","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"就算是放长假，我也不打算中断练习喔。","en":"Even if it's a long holiday, I don't want to slack off on my training.","ja":"長期休みだとしても稽古を休むつもりはないよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_8#originalText","id":"talk.vc.home_event_eugeo_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"在多雨的季节中，食物的天命会瞬间减少，必须要注意。","en":"The life span of foods depletes quickly on rainy days. Be careful.","ja":"雨が多い時期は、食べ物の天命があっという間に減るから、気をつけないと"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_9#originalText","id":"talk.vc.home_event_eugeo_9","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"即使一年只限一次，假如可以见到珍爱的人，我想还是会很开心的。","en":"Even though it only happens once a year, I'm sure Orihime and Hikoboshi are happy to see each other on Tanabata.","ja":"年に一度だとしてももし大切な人に会えるならうれしいと思うよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_10#originalText","id":"talk.vc.home_event_eugeo_10","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"夏至祭典的声音连这里都听得见呢。大家好像都很开心的样子。","en":"I can hear the sounds from the summer festival all the way out here. It sounds like so much fun.","ja":"夏至祭の音が、ここまで聞こえてくるねみんな楽しそうだ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_11#originalText","id":"talk.vc.home_event_eugeo_11","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我不会帮你做作业喔。你早就知道今天是假期的最后一天了吧？","en":"I'm not helping you with your assignment. You knew today was the last day of vacation!","ja":"課題の手伝いならしないよ今日休みが終わるってわかっていたことじゃないか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_12#originalText","id":"talk.vc.home_event_eugeo_12","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"要把团子供奉给月亮吗？在这个季节的话，天命也不会那么容易减少吧。","en":"You're supposed to offer rice cakes to the moon? I guess their life span would last a while in this weather.","ja":"月にお団子を供えるの? この時期なら、天命もそんなに減らないかな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_13#originalText","id":"talk.vc.home_event_eugeo_13","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"要穿成这样出门实在是……","en":"I'm a little too embarrassed to go out in public dressed like this.","ja":"この格好をして外に出るのはさすがに……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_15#originalText","id":"talk.vc.home_event_eugeo_15","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"圣诞节……是吗？名字真响亮呢。而且餐点也很丰盛。","en":"Christmas, huh... It has a nice ring to it. And would you look at that feast!","ja":"クリスマス……かキレイな響きだねそれに、すごいご馳走だ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_1#originalText","id":"talk.vc.home_event_kirito_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"新年快乐！今年也多多指教喔。","en":"Happy New Year! Let's make it a good one.","ja":"明けましておめでとう!今年もよろしくな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_2#originalText","id":"talk.vc.home_event_kirito_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"听说只要吃下和年龄一样多的豆子，一整年就会健健康康的。你要确实吃豆子喔。","en":"They say if you eat as many beans as your age, you'll have a healthy year.So eat up!","ja":"年の数だけ豆を食べれば一年間健康に過ごせるらしいぞしっかり食べとけよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_3#originalText","id":"talk.vc.home_event_kirito_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天是情人节啊？总觉得肚子饿了……","en":"So today is Valentine's Day... I'm getting hungry.","ja":"今日はバレンタイン、かなんだか腹がへってきたな……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_4#originalText","id":"talk.vc.home_event_kirito_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"女儿节这天，我们这群男生该做什么才好？","en":"Hinamatsuri is for girls. So how should guys like me celebrate it?","ja":"ひな祭りって俺ら男は何をすればいいんだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_5#originalText","id":"talk.vc.home_event_kirito_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"白色情人节啊？我真的很不擅长这种事情耶。到底要送什么东西才好……","en":"White Day, huh... I always kind of dread it. I never know what to give people.","ja":"ホワイトデーかぁ苦手なんだよなぁこういうの何を贈ればいいのやら……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_6#originalText","id":"talk.vc.home_event_kirito_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嘿嘿，今天要来怎么整人呢？","en":"Hehe. What kind of pranks should I pull today?","ja":"へへ、今日はどんなビックリを提供しようかな? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_7#originalText","id":"talk.vc.home_event_kirito_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"偶尔出个远门，外宿过夜怎么样？","en":"Wanna go on an overnight trip?","ja":"たまには泊りがけで遠出するなんてどうだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_8#originalText","id":"talk.vc.home_event_kirito_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"呃啊……湿气这么重，就开始想把衣服脱了。","en":"Ugh... When it's this hot and humid, I just feel like taking off, like, all my clothes.","ja":"うへぇ……こう湿気がすごいと服脱ぎたくなるな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_9#originalText","id":"talk.vc.home_event_kirito_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我在寻找我的织女，结果就找到这里来了。","en":"I was searching for my Orihime. That's why I'm here.","ja":"俺の織姫を探してたらここに辿り着いたってわけだ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_10#originalText","id":"talk.vc.home_event_kirito_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好像有在举办祭典耶！一起去看看吧！！","en":"I hear there's a festival.  Let's check it out!","ja":"お祭りやってるらしいぞ!一緒に行こうぜ!!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_11#originalText","id":"talk.vc.home_event_kirito_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……欸、我说……要不要到我的房间一起……做作业……？","en":"So, hey... Wanna do homework in my room with me?","ja":"……な、なぁ……俺の部屋で一緒に宿題やらないか……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_12#originalText","id":"talk.vc.home_event_kirito_12","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"月亮好美喔……啊！我、我只是纯粹说说感想，没有其他意思喔！","en":"The moon sure is pretty tonight. It's so romantic... Er, I didn't mean anything by that!","ja":"月が綺麗だな……あ!こ、これはそのままの感想で深い意味とかはないからな!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_13#originalText","id":"talk.vc.home_event_kirito_13","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不给糖……就捣蛋～！！","en":"Trick or treeeat!","ja":"お菓子くれないと……いたずらするぞおー!!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_14#originalText","id":"talk.vc.home_event_kirito_14","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天啊，是过去那一切的开端。","en":"Today is the day it all began.","ja":"今日は、さすべてが、始まった日なんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_kirito_15#originalText","id":"talk.vc.home_event_kirito_15","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"圣诞快乐。今天一起去吃大餐吧！","en":"Merry Christmas! Let the feast begin!","ja":"メリークリスマス今日はご馳走食べようぜ!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_1#originalText","id":"talk.vc.home_event_leafa_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"新年快乐！希望大家今年也身体健康，平平安安。","en":"Happy New Year! I hope everyone has a happy and healthy year!","ja":"あけましておめでとう今年も一年、みんな健康で無事に過ごせますように"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_2#originalText","id":"talk.vc.home_event_leafa_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"惠方卷啊，就是没办法一口气吃完对吧。","en":"Setsubun sushi rolls are always impossible to eat in one bite.","ja":"恵方巻きって、全部いっぺんには食べきれないよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_3#originalText","id":"talk.vc.home_event_leafa_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我今年试着做成巧克力饼干。这样玩游戏或念书的时候，就能轻松食用了嘛。","en":"I made you a chocolate cake this year. This way, you can easily sneak in bites while you're studying or gaming.","ja":"今年はチョコクッキーにしてみたんだこれなら、ゲームとかお勉強の時でも簡単につまめるでしょ? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_4#originalText","id":"talk.vc.home_event_leafa_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"因为今天的主角是女孩子，所以我可以尽情撒娇吧？","en":"Today is the day where girls are the star, so shower us with affection, okay?","ja":"今日は女の子が主役の日だからたくさん甘えていいよね? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_5#originalText","id":"talk.vc.home_event_leafa_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"嘿嘿，谢谢你。收到回礼果然会很开心呢。","en":"Hehe, thank you. I do love getting thank-you gifts.","ja":"えへへ、ありがとうやっぱり、お返しもらえるとうれしいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_6#originalText","id":"talk.vc.home_event_leafa_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我一直在想怎样才能骗到你，结果昨天就熬夜了……呼哇……","en":"I was trying to come up with a good April Fool's prank, and before I knew it, I'd stayed up all night.","ja":"どんな嘘で驚かせようかって考えてたら、昨日夜更かししちゃって……ふわあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_7#originalText","id":"talk.vc.home_event_leafa_7","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"连假的时候大家一起外宿也不错呢。也邀请亚丝娜和莉兹她们吧。","en":"I'd love to go away somewhere on vacation with the gang. You know, like Asuna and Liz.","ja":"連休は、みんなでお泊り旅行もいいよね。アスナさんとか、リズさんたちも誘って"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_8#originalText","id":"talk.vc.home_event_leafa_8","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"好潮湿啊。洗好的衣服也晾不干，夏天可不可以快点来啊？","en":"It's really humid today, huh? This laundry won't dry on the line. Can it be summer already?","ja":"なんか蒸し蒸しするね洗濯物も乾かないし早く夏にならないかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_9#originalText","id":"talk.vc.home_event_leafa_9","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"听说今天晚上会有七夕烟火呢！欸，我们一起去看嘛。","en":"I hear there's going to be fireworks tonight for Tanabata! Let's go see them!","ja":"今日の七夕、夜は花火があるんだって! ねえ、一緒に見に行こうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_10#originalText","id":"talk.vc.home_event_leafa_10","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"嘿嘿，我买了新泳装，所以大家一起去游泳池吧！","en":"Hehe, I bought a new swimsuit, so let's all go swimming!","ja":"へへ、新しい水着を買ったからみんなでプールに行こうよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_11#originalText","id":"talk.vc.home_event_leafa_11","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"欢乐的暑假也结束了呢，明天开始又要上学啊～","en":"It's sad summer vacation is almost over. Agh. I have to go to school tomorrow.","ja":"楽しい夏休みも終わっちゃうね明日から、また学校かあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_12#originalText","id":"talk.vc.home_event_leafa_12","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我们曾经一起把团子都吃光，结果就挨骂了呢。好怀念啊。","en":"Remember when we were kids and ate all the rice cakes and got yelled at? Those were the days, huh?","ja":"昔、いっしょにお団子全部食べちゃって、怒られたよね懐かしいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_13#originalText","id":"talk.vc.home_event_leafa_13","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"小时候，我们有一起装扮成鬼怪，在附近邻居间打转呢。那时候真好玩。","en":"I remember wandering around the neighborhood dressed as ghosts when we were little. That was so much fun.","ja":"小さい頃は、一緒にお化けの格好でご近所を回ったよねすごく楽しかった"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_14#originalText","id":"talk.vc.home_event_leafa_14","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天是令人忘不了的日子唷。……不过，你还是回来了，所以我现在才有办法不哭。","en":"Today is a day I'll never forget. But...you came back home in the end. So I don't have to cry this year.","ja":"今日は忘れられない日だよ……でも、帰ってきてくれたからだから、今は泣かずにいられるの"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_15#originalText","id":"talk.vc.home_event_leafa_15","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"圣诞快乐！今天有很多好吃的，你要多吃一点喔。","en":"Merry Christmas! We've got a big feast, so loosen your belt!","ja":"メリークリスマス! 今日はご馳走たっくさんだからいっぱい食べてね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_1#originalText","id":"talk.vc.home_event_lisbeth_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"新年快乐！我们今年也要彼此多加油喔。","en":"Happy New Year! Let's both make it a good one.","ja":"あけましておめでとう今年も頑張りましょうねお互いに"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_2#originalText","id":"talk.vc.home_event_lisbeth_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"喂，你刚刚砸真的是吧！你要是那么打算，那我也不会跟你客气喔！","en":"Wow, you threw those beans like you meant it! Fine. Two can play at that game!","ja":"ちょっと、本気でぶつけたでしょ! そっちがその気ならあたしだってやるからね! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_3#originalText","id":"talk.vc.home_event_lisbeth_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"你还是一样收这么多啊？小心别吃太多变胖！","en":"Look who's got lots of chocolate again. If you eat aaall of those, you’ll get so big!","ja":"相変わらずもらってるわね食べすぎて太らないよーに! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_4#originalText","id":"talk.vc.home_event_lisbeth_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"装饰在女儿节娃娃前面的箱子，看起来很像宝箱对吧。","en":"The box we keep the hina dolls in, doesn't it remind you of a treasure chest?","ja":"お雛様に飾ってある箱なんか宝箱っぽいわよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_5#originalText","id":"talk.vc.home_event_lisbeth_5","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"白色情人节的时候啊，我可能想收一些时髦的小东西。","en":"So, for White Day, I'd like cute little accessory or something.","ja":"ホワイトデーはねえちょっとおしゃれな小物とかほしいかも"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_6#originalText","id":"talk.vc.home_event_lisbeth_6","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"最近到处都在进行整人企划呢，我也要想些点子才行。","en":"Everyone seems to be scheming up some prank. I guess I'd better come up with my own plan.","ja":"最近は、どこでもウソ企画ってやってるわよねあたしもなにか考えないと"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_7#originalText","id":"talk.vc.home_event_lisbeth_7","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"黄金周啊。我们要不要调整一下假期，一起去哪里走走？","en":"Wanna go somewhere for Golden Week?","ja":"ゴールデンウィーク休みをあわせてどっかにいかない? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_8#originalText","id":"talk.vc.home_event_lisbeth_8","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"呀，打雷！？我很怕雷声啦……","en":"Eek! Was that thunder?! That sound always freaks me out.","ja":"きゃっ、雷!?あの音、苦手なのよね……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_9#originalText","id":"talk.vc.home_event_lisbeth_9","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"换作是我的话，应该会在银河搭一座桥，然后就每天都能见面了。","en":"If I were Orihime, I'd build a bridge across the Milky Way so I could see Hikoboshi every day, instead of just once a year.","ja":"あたしだったら、天の川に橋を作って、毎日会えるようにしちゃうかも"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_10#originalText","id":"talk.vc.home_event_lisbeth_10","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"这个季节去南方海域不错呢，因为水很清澈嘛。","en":"I always feel like going to the tropics in the summer. I love how clear the water is down there.","ja":"この季節は南の海とかいいわね。水が透き通ってて"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_11#originalText","id":"talk.vc.home_event_lisbeth_11","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"受不了，你的作业还没写完喔？你不是说有订下进度表吗？","en":"You still haven't finished your summer homework? But I thought you said you made yourself a schedule.","ja":"え? まだ宿題終わってないの? 計画立てたって言ってたじゃない"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_12#originalText","id":"talk.vc.home_event_lisbeth_12","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"往年都是错过了才想起要赏月……真是幸好今年有赏到。","en":"Every year, I always somehow miss the Moon Festival. Good thing I didn't forget this year.","ja":"お月見って、毎年気がついたら終わっちゃってるから……今年は見られてよかったな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_13#originalText","id":"talk.vc.home_event_lisbeth_13","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"我的店里也来办万圣节活动好了？例如南瓜盾牌之类的。","en":"Maybe I'll hold a Halloween event at my shop? Make pumpkin helmets or something.","ja":"うちの店もハロウィンのイベントやろうかなカボチャの盾、とか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_14#originalText","id":"talk.vc.home_event_lisbeth_14","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"今天是初始之日呢。就连那个世界，如今想起都还是会有点怀念。","en":"Today is the anniversary of that launch of that game, huh? Looking back now, I actually have some fond memories of that world.","ja":"今日が始まりの日、だったわねあの世界も、今思うと少し懐かしい気がするの"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_15#originalText","id":"talk.vc.home_event_lisbeth_15","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"说到圣诞节，就会想到一整块的大蛋糕呢。呵呵，听起来真好吃！","en":"You can't have Christmas without a big Christmas cake! Hehe. Now I'm hungry.","ja":"クリスマスといえば、大きなホールケーキよねふふ、おいしそう! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_mary_1#originalText","id":"talk.vc.home_event_mary_1","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"从今天开始就是新的一年了！新年快乐！真开心又能平安迎接新年！","en":"A new year starts today. Happy New Year! I'm so glad we get to spend it together.","ja":"今日から新しい年ね!おめでとう!無事に迎えられて、うれしい!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mary_2#originalText","id":"talk.vc.home_event_mary_2","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"要拿鱼头当装饰？可以是可以，不过结束以后我会拿来煮晚餐喔。","en":"Use the fish head as decoration? I don't really mind, but we're eating that for dinner later.","ja":"お魚の頭を飾るの?いいけど、終わったら晩ご飯のおかずにするからね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mary_3#originalText","id":"talk.vc.home_event_mary_3","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"做点心的日子？这样要准备牛奶、砂糖和……讨厌，妳怎么不早点说嘛！","en":"You're supposed to make candy? Then we'll need milk, sugar... Oh, why didn't you say so sooner!","ja":"お菓子作りをする日なの?だったら、ミルクと、お砂糖と……もう、それならもっと早く言ってよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mary_4#originalText","id":"talk.vc.home_event_mary_4","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"我还不能喝酒……咦？这个没关系？甜甜的很好喝？","en":"I'm too young to drink... Oh? I'm allowed to drink this liquor? It's sweet and delicious, you say?","ja":"わたしは、まだお酒は……え、これは飲んでいいの?甘くておいしいの?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mary_5#originalText","id":"talk.vc.home_event_mary_5","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"今天也能收到点心吗？明明前阵子才刚收过……不过，我很高兴！","en":"I get candy again today? Even though you just gave me some last month? Well, I'm still thankful!","ja":"今日もお菓子をもらえるの?この間ももらったのに……でも、うれしい!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mary_6#originalText","id":"talk.vc.home_event_mary_6","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"其实说这是「可以说谎的日子」才是骗人的吧？这摆明就是不对的事情啊。","en":"A day where it's okay to lie... Isn't that idea itself a lie? It's just wrong!","ja":"「嘘をついていい日」なんてそれが実は嘘なんじゃない?だって、そんなのダメだもの"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mary_7#originalText","id":"talk.vc.home_event_mary_7","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"只要姊姊休假时可以一直待在这里，我就很满足了。","en":"For this extended holiday, all I want is for you and me to spend all our time together.","ja":"わたしはお休みの間お姉ちゃんがずっとここにいてくれれば、それだけでいいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mary_8#originalText","id":"talk.vc.home_event_mary_8","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"接连两天都下雨……雨天会让面包跟肉的天命变少，真伤脑筋。","en":"Rain, both yesterday and today! That's bad... Bread and meat have shorter lifespans on rainy days.","ja":"昨日も今日も雨なのね……パンもお肉も、雨の日は天命が少なくて……困っちゃう"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mary_9#originalText","id":"talk.vc.home_event_mary_9","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"把心愿写在纸上告诉史提西亚大人吗？既然这样，当然是挂高一点才好嘛。","en":"So we write our wishes on these papers and Stacia grants them? We should place ours at the top.","ja":"この紙に書いて、お願いをステイシア様に届けるのねだったら、上の方に飾るのがいいよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mary_10#originalText","id":"talk.vc.home_event_mary_10","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"夏至祭典是我一年之中最期待的祭典。在外面用餐真的特别美味呢。","en":"The Summer Festival is the biggest of the year. Food just tastes better when you eat it outdoors!","ja":"夏至祭は、一年で一番楽しみなお祭りなの外で食べるご飯、おいしいよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mary_11#originalText","id":"talk.vc.home_event_mary_11","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"夏天的假期，一起去了好多地方玩呢。希望明年夏天我们也能一起出去玩。","en":"We sure had a lot of fun this summer vacation. I hope we have as much fun together next year.","ja":"夏のお休み、いっぱい遊べたねまた来年の夏も、ふたりで遊びに行けたらいいな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mary_12#originalText","id":"talk.vc.home_event_mary_12","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"今天的露那利亚大人很漂亮，我可以晚点再睡吗？","en":"Can we stay outside a bit later than usual tonight? Lunaria is just so beautiful.","ja":"今日はルナリア様がキレイだから少しだけ夜更かししてもいい?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mary_13#originalText","id":"talk.vc.home_event_mary_13","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"这种假扮魔物的日子，不会被贝库达抓起来吗？我可能有点害怕……","en":"We're supposed to dress up as monsters today? I'm scared. What if Vecta catches us?","ja":"魔物のふりをする日だなんてベクタに捕まらないのかな?わたしは、ちょっと怖いかも……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_mary_15#originalText","id":"talk.vc.home_event_mary_15","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"一起床就发现礼物放在枕头边……？要是有这种事，大家一定会很高兴的。","en":"There will be a present under my pillow when I wake? I can see why everyone loves this holiday.","ja":"起きたら贈り物が枕元に……?そんなことがあったら、きっとみんなとっても喜ぶと思うわ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_1#originalText","id":"talk.vc.home_event_ronye_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"新年快乐……这就是《艾恩葛朗特流》的拜年啊。","en":"Happy New Year! This is an Aincrad Style seasonal greeting, right?","ja":"あけましておめでとう……これが《アインクラッド流》の新年のご挨拶なんですね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_2#originalText","id":"talk.vc.home_event_ronye_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"用豆子驱赶恶鬼……真是不可思议的仪式呢。","en":"Exorcising evil spirits by throwing beans... An intriguing ceremony indeed.","ja":"豆で悪鬼を払う……不思議な儀式ですね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_3#originalText","id":"talk.vc.home_event_ronye_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长，你拿了好多点心喔……不过，也请品尝我的吧！","en":"I see you have a lot of sweets already. Still...here! Have mine, too!","ja":"先輩、お菓子たくさん持っていますね……でも、私のも食べてください! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_4#originalText","id":"talk.vc.home_event_ronye_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"好可爱的人偶。这是要嫁出去的女孩子吗？","en":"What adorable little dolls. Is this a bridal doll?","ja":"かわいいお人形ですねこちらが、お嫁に行く女の子ですか? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_5#originalText","id":"talk.vc.home_event_ronye_5","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"您，要给我点心……？非常感谢您！我会珍惜一辈子的！","en":"You got sweets...for me? Thank you so much! I will cherish this memory always!","ja":"私に、お菓子を……? ありがとうございます! 一生大切にします! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_6#originalText","id":"talk.vc.home_event_ronye_6","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"不可以说谎啦，学长。怎么可能会有那种可以骗人的日子呢？","en":"You must never tell lies, sir. A day where lies are not taboo? No such day exists!","ja":"嘘はダメですよ、先輩嘘を付いてもいい日、なんてあるわけありません"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_7#originalText","id":"talk.vc.home_event_ronye_7","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"连续好几天的安息日……好像作梦一样。","en":"Just imagine...consecutive days of rest. It feels like a dream.","ja":"何日も安息日が続くなんて……なんだか夢みたいです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_8#originalText","id":"talk.vc.home_event_ronye_8","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"雨天的时候，学长大多会待在房里，所以我并不讨厌。","en":"I don't mind rainy days much, because that means you're in your room.","ja":"雨の日は、先輩が部屋にいることが多いのであんまり嫌いじゃないです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_9#originalText","id":"talk.vc.home_event_ronye_9","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"将愿望写在纸上吗？呵呵，这种事好像会在童话故事里出现呢。","en":"We write our wishes on the slips of paper? Hehe, this does feel like a fairytale.","ja":"願い事を紙に書くのですか? ふふ、なんだか昔話に出てきそうな感じです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_10#originalText","id":"talk.vc.home_event_ronye_10","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"再过几天就是夏至祭典了。学长，当天还会有很多好吃的摊贩喔！","en":"It's almost the Summer Festival. Oh, you'll love all the food stalls!","ja":"もうすぐ夏至祭です先輩、おいしい屋台もたくさん出るんですよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_11#originalText","id":"talk.vc.home_event_ronye_11","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学院的作业……做不完。我今天，写了一整天的作业。","en":"The school assignments just never end... I'll be spending the entire day doing school work.","ja":"学院の課題……終わらないです今日は一日、ずっと課題です"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_12#originalText","id":"talk.vc.home_event_ronye_12","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"好漂亮的月亮……虽然过了门禁时间，但能赏到月真是太好了。","en":"What a beautiful moon. I'm glad I get to see it, even if I had to break curfew.","ja":"すごくキレイな月……門限を破っちゃいましたけど見られてよかったです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_13#originalText","id":"talk.vc.home_event_ronye_13","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"扮装……感觉很有趣！但是，请您不要做恐怖打扮喔！","en":"Costumes...how amusing! But will you please stop scaring me?","ja":"仮装……面白そうです! でも、怖いのはやめてくださいね? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_15#originalText","id":"talk.vc.home_event_ronye_15","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"哇啊，有蛋糕跟大餐……这么豪华的宴会，我还是第一次参加！","en":"Wow, look at that feast and that cake! I've never attended a banquet so elaborate!","ja":"うわあ、ケーキにごちそう……こんな豪華な宴会は初めてです! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_1#originalText","id":"talk.vc.home_event_silica_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"新年快乐。能和你一起迎接新年，我非常开心。","en":"Happy New Year! I'm really happy I get to ring it in with you.","ja":"あけましておめでとうございます新年を一緒に迎えられてとってもうれしいです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_2#originalText","id":"talk.vc.home_event_silica_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"鬼面具……实在是太写实了，有点恐怖呢……","en":"That demon's mask... It looks real. Too real...","ja":"鬼のお面……凄くリアルでちょっと怖いですね……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_3#originalText","id":"talk.vc.home_event_silica_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"不介意的话，也请尝尝我的巧克力！","en":"I have chocolates, too. Have some, if you'd like!","ja":"あたしのチョコレートもよかったら食べてください! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_4#originalText","id":"talk.vc.home_event_silica_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"如、如果是甜酒，我可以喝一点！热热的很好喝呢。","en":"Oh, sure! I could have a little amazake. I love it! So sweet and warm.","ja":"あ、甘酒ならちょっと飲めます! あったかくておいしいですよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_5#originalText","id":"talk.vc.home_event_silica_5","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"虽然今天是白色情人节，但我也可以送你礼物吗？","en":"Today is White Day... So, uh, I have a present for you.","ja":"今日はホワイトデーですけどあたしからもプレゼントお渡ししてもいいですか? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_6#originalText","id":"talk.vc.home_event_silica_6","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"呜呜，我今天，绝对不会被任何人骗！","en":"Eek, I'm not letting anyone fool me today!","ja":"うう、今日は絶対、誰にも騙されません! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_7#originalText","id":"talk.vc.home_event_silica_7","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"希望在黄金周的时候，大家也都可以聚在一起。就算是在《ALO》里面也不要紧。","en":"I hope we can get the gang together for Golden Week. We could meet up in ALO or something.","ja":"ゴールデンウィークはみんなで集まれるといいですね《ALO》の中でもいいですし"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_8#originalText","id":"talk.vc.home_event_silica_8","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"外面雨下得好大……今天就待在家里吧。","en":"It's really pouring out there. Let's spend the day indoors.","ja":"外は雨がすごいですね……今日はおうちで過ごしましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_9#originalText","id":"talk.vc.home_event_silica_9","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"七夕的传说呀，很浪漫对吧。","en":"The Tanabata legend... It's very romantic, don't you think?","ja":"七夕の伝説ってとってもロマンチックですよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_10#originalText","id":"talk.vc.home_event_silica_10","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"如果要去海水浴场，是不是该买新泳装了呢？","en":"If we're going to the beach, maybe I should get a new swimsuit.","ja":"海水浴に行くなら新しい水着を買おうかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_11#originalText","id":"talk.vc.home_event_silica_11","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"作业吗……我……已经写完了。不好意思……","en":"Summer homework? Sorry, I already finished mine.","ja":"宿題ですか……あたしは、終わらせちゃいましたすみません……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_12#originalText","id":"talk.vc.home_event_silica_12","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"说不定，虚拟世界的月亮上，真的会有兔子呢。","en":"You know, there might actually be a virtual world where the moon is made of cheese.","ja":"もしかしたら、仮想世界の月には、ちゃんとウサギがいるかもしれませんね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_13#originalText","id":"talk.vc.home_event_silica_13","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"这次的万圣节，我也想帮毕娜扮装。","en":"I was thinking of dressing up Pina for Halloween this year.","ja":"今度のハロウィンはピナにも仮装させようかなって思ってるんです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_14#originalText","id":"talk.vc.home_event_silica_14","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"虽然碰上了很多恐怖的事情，但我还是很庆幸自己有玩《SAO》。","en":"Even though I had a lot of traumatic experiences, I'm still glad I lived through SAO.","ja":"怖い思いもたくさんしたけどあたしは《SAO》やっててよかった、と思ってます"},"kind":"dialogue"},{"uid":"talk.vc.home_event_silica_15#originalText","id":"talk.vc.home_event_silica_15","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"我试着让毕娜戴上驯鹿的角了。你觉得如何呢……","en":"I put reindeer antlers on Pina. How does she look?","ja":"ピナにトナカイの角、着けてみましたどうでしょうか……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_1#originalText","id":"talk.vc.home_event_sinon_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"新年快乐！希望这一整年，都不要被扯进麻烦中。","en":"Happy New Year! I hope it's an uneventful year this time.","ja":"あけましておめでとう今年はトラブルに巻き込まれない一年になるといいわね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_2#originalText","id":"talk.vc.home_event_sinon_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"节分的豆子对鬼的眼睛很有效啊……原来如此，和烟跟瓦斯是一样的效果。","en":"So, the beans you throw on Setsubun are supposed make demons blind? That makes sense. Kind of like tear gas or smoke.","ja":"節分の豆は鬼の目に効くのね……なるほど、スモークやガスと同じ効果なんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_3#originalText","id":"talk.vc.home_event_sinon_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"不用摆出那么渴望的表情，我有好好准备你的份啦。来，巧克力。","en":"Jeez, stop staring. I can take a hint. Here. Happy Valentine's Day.","ja":"そんな物欲しそうな顔しなくてもちゃんとあるわよはい、チョコレート"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_4#originalText","id":"talk.vc.home_event_sinon_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"小小的女儿节娃娃我也喜欢。因为它们虽然不太主张自己的存在，但做工还是一样精细。","en":"I prefer the really tiny Hina dolls. They may not look very powerful, but they're very carefully made.","ja":"私は小さいお雛様も好きあんまり自己主張は強くないけど作りがしっかりしているから"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_5#originalText","id":"talk.vc.home_event_sinon_5","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"嗯，谢谢。我会好好珍惜这个的。","en":"Thanks. I'll treasure this.","ja":"うん、ありがとう大事にするね、これ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_6#originalText","id":"talk.vc.home_event_sinon_6","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"我觉得没必要刻意去骗人，不过有趣的恶作剧倒是没差。","en":"I don't think you need to lie just because it's April Fools Day. I'm up for a fun prank, though.","ja":"わざわざ嘘をつかなくてもいいと思うわ楽しいイタズラならいいけど"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_7#originalText","id":"talk.vc.home_event_sinon_7","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"黄金周，我们找个人没那么多的地方悠闲度过吧。","en":"For Golden Week, let's spend our time in a not-so-crowded place.","ja":"ゴールデンウィークあんまり人が多くないところでゆっくり過ごしましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_8#originalText","id":"talk.vc.home_event_sinon_8","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"雨天骑车很麻烦吧？小心点喔。","en":"Isn't it hard to ride a bike in the rain? Be careful out there.","ja":"雨の日はバイクに乗るの大変でしょう? 気をつけてね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_9#originalText","id":"talk.vc.home_event_sinon_9","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"一年只见面一次还能维系感情，大概代表双方的思念就是如此强烈吧……","en":"Orihime and Hikoboshi keep loving each other even though they only meet once a year? That's some strong love right there.","ja":"年に1回でも想いが続くのはそれだけふたりの絆が強いってことなんでしょうね……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_10#originalText","id":"talk.vc.home_event_sinon_10","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"这是我在祭典的打靶摊位拿下的奖品喔。有点对不起那摊位呢。","en":"I won this prize at a festival shooting booth. I feel kind of like I scammed the booth, though.","ja":"これ、お祭りの射的で取ってきた景品よあの店には悪いことしちゃったわ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_11#originalText","id":"talk.vc.home_event_sinon_11","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"作业那种东西我早就写完了。我可不会帮你喔。","en":"I finished my summer homework ages ago. And I'm not helping you with yours.","ja":"宿題なんて、とっくに終わってるわよ私は手伝わないからね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_12#originalText","id":"talk.vc.home_event_sinon_12","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"今年的月亮真美。为什么呢……","en":"The moon looks extra-pretty this year. I wonder why that is...","ja":"今年の月はキレイねどうしてだろう……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_13#originalText","id":"talk.vc.home_event_sinon_13","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"我希望你别来捣蛋，所以先给糖果吧。来，给你。","en":"I don't want any tricks, so here's your treat.","ja":"イタズラはやめてほしいから先にお菓子を渡しておくわはい、これ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sinon_15#originalText","id":"talk.vc.home_event_sinon_15","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"圣诞节啊。我们在温暖的家中一起庆祝……感觉真幸福呢。","en":"Merry Christmas. Celebrating indoors where it's nice and warm... Can life get any better than that?","ja":"メリークリスマス暖かい家の中で、一緒にお祝いしていると……なんだか幸せなの"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sortiliena_1#originalText","id":"talk.vc.home_event_sortiliena_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你想好今年的抱负了吗？订立明确的目标可是很重要的喔。","en":"Have you chosen your New Year's resolution yet? Setting and achieving goals is very important.","ja":"新年の抱負は決まったか? しっかり目標を定めるのが大切だぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sortiliena_2#originalText","id":"talk.vc.home_event_sortiliena_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"真是不可思议的风俗习惯……但是很有趣。不知是否可以采用到战斗里……","en":"What an odd custom... Odd, but fun. I don't suppose we could use it in wars, though.","ja":"不思議な風習だな……だが面白い。戦闘にも取り入れられないだろうか……"},"kind":"dialogue"}]};
